// A read-only landscape plot of completed physical shots. No DOM or match work while hidden.
var shotReportFilter='all',shotReportSelection=null;
function shotReportMarkup(match,context={}){
 const d=ShotReport.read(match,{team:shotReportFilter,selected:shotReportSelection}),esc=escapeText;if(!d.valid)return '<p class="match-report-empty">이 경기의 슈팅 위치 기록이 없습니다.</p>';
 shotReportSelection=d.selected?.key||null;const selected=d.selected,limit=Math.max(40,...d.rows.map(r=>r.y+3)),choices=d.rows.map(r=>'<option value="'+esc(r.key)+'" '+(r.key===shotReportSelection?'selected':'')+'>'+esc(r.minute+'′ · '+(r.team?'상대 ':'우리 ')+r.name+' · '+r.label)+'</option>').join('');
 const marks=d.rows.map(r=>{const color=r.team?'#ffb588':'#9edcff',at='x="'+r.x.toFixed(2)+'" y="'+r.y.toFixed(2)+'"',mark=r.outcome==='goal'?'<text '+at+' text-anchor="middle" dominant-baseline="central" font-size="3.1" fill="'+color+'">★</text>':'<circle cx="'+r.x.toFixed(2)+'" cy="'+r.y.toFixed(2)+'" r="1" fill="'+color+'" stroke="#193b32" stroke-width=".35"/>';return '<g data-shot-mark="'+esc(r.key)+'"><title>'+esc(r.minute+'′ '+r.name+' '+r.label)+'</title>'+mark+'</g>';}).join('')+(selected?'<circle data-shot-selected="'+esc(selected.key)+'" cx="'+selected.x.toFixed(2)+'" cy="'+selected.y.toFixed(2)+'" r="2.2" fill="none" stroke="white" stroke-width=".35"/>':'');
 const portrait=selected&&typeof Portraits!=='undefined'?Portraits.html({identity:selected.identity,name:selected.name}):'',person=selected?'<div class="shot-person">'+portrait+'<div><b>'+esc(selected.name)+'</b><span>'+esc(selected.minute)+'′ · '+esc(selected.label)+'</span></div></div><p class="shot-measures">거리 <b>'+selected.range+'m</b> · xG <b>'+(selected.xg===null?'미등록':selected.xg.toFixed(2))+'</b> · '+(selected.inBox?'박스 안':'박스 밖')+'</p>':'<p class="shot-empty">슈팅 장면이 끝나면 위치와 결과를 표시합니다.</p>';
 const rows=d.totals.map((r,i)=>'<tr><th>'+(i?'상대':'우리')+'</th><td>'+r.shots+'</td><td>'+r.onTarget+'</td><td>'+r.xg.toFixed(2)+'</td><td>'+r.goals+'</td></tr>').join('');
 return '<section class="shot-workspace" aria-label="완료된 실제 슈팅 위치"><div class="shot-filter-row"><select id="shot-report-team" aria-label="슈팅 팀 필터">'+[['all','두 팀 전체'],['ours','우리 팀'],['theirs','상대 팀']].map(([id,label])=>'<option value="'+id+'" '+(id===d.team?'selected':'')+'>'+label+'</option>').join('')+'</select><select id="shot-report-select" aria-label="슈팅 장면 선택" '+(!d.rows.length?'disabled':'')+'>'+(choices||'<option>기록된 슈팅 없음</option>')+'</select></div><div class="shot-body"><figure class="shot-diagram"><svg viewBox="-3 -5 74 '+(limit+8)+'" role="img" aria-label="두 팀 공격 방향을 위로 맞춘 슈팅 위치"><rect x=".5" y="0" width="67" height="105" fill="#1a4235" stroke="#8cae9d" stroke-width=".3"/><g fill="none" stroke="#8cae9d" stroke-width=".3"><path d="M13.84 0V16.5H54.16V0M24.84 0V5.5H43.16V0M30.34 0V-1.8H37.66V0M.5 52.5H67.5"/><circle cx="34" cy="11" r=".2"/><path d="M26.7 16.5A9.15 9.15 0 0 0 41.3 16.5"/></g>'+marks+'</svg></figure><aside class="shot-detail"><table><caption>'+esc((context.own||'우리')+' '+match.score.join(' : ')+' '+(context.opponent||'상대'))+'</caption><thead><tr><th>기록</th><th>슈팅</th><th>유효</th><th>xG</th><th>표시 골</th></tr></thead><tbody>'+rows+'</tbody></table><p class="shot-mini-totals">슈팅 <b>'+d.totals[0].shots+':'+d.totals[1].shots+'</b> · 유효 <b>'+d.totals[0].onTarget+':'+d.totals[1].onTarget+'</b> · 골 <b>'+d.totals[0].goals+':'+d.totals[1].goals+'</b></p>'+person+'</aside></div><p class="shot-note">'+esc(d.note)+' · <span>● 우리</span> <span>● 상대</span> ★ 득점</p></section>';
}
